//! The four bundled faces, their static cuts, and the typesetting helper.
//!
//! GPUI registers a variable font as a single face (its default instance) and
//! never applies `wght`, `wdth` or `opsz`, so every weight the type ladder
//! uses is shipped as a static cut (`resources/fonts/static`, generated by
//! `resources/fonts/instance.py`). Families:
//!
//! | family | cuts | used for |
//! |---|---|---|
//! | `Bricolage Grotesque` | 520 / 620 / 650 / 720, opsz 18 | text-size display heads |
//! | `Bricolage Grotesque Display` | 620 / 640, opsz 96 | [`ty::DISPLAY`], [`ty::DISPLAY_XL`] |
//! | `Bricolage Grotesque Hero` | 640, opsz 96, wdth 92 | [`ty::HERO`] |
//! | `Bricolage Grotesque Book` | 640, opsz 17, wdth 95 | [`ty::BOOK`] |
//! | `Geist` | 400 / 500 / 600 / 700 | UI |
//! | `Geist Mono` | 400 (variable default), 500, 600 | identifiers |
//! | `Newsreader` | italic 400 opsz 14; upright variable default | serif below 17 px |
//! | `Newsreader Lede` | italic 400 opsz 19 | [`ty::LEDE`] and larger serif |
//!
//! Views never name a family: they call [`Typeset::typeset`] with a
//! [`TypeRole`] and the active [`Facet`].

use crate::theme::Facet;
use crate::tokens::{Face, TypeRole, ty};
use gpui::{App, FontFeatures, FontStyle, FontWeight, SharedString, Styled, px};
use sha2::{Digest, Sha256};
use std::borrow::Cow;
use std::fmt;
use std::sync::{Arc, LazyLock};

#[cfg(feature = "gallery")]
pub(crate) mod gallery;

/// One embedded font file.
#[derive(Clone, Copy, Debug)]
pub struct Cut {
    /// The file name under `resources/fonts`.
    pub file: &'static str,
    /// The family name `CoreText` resolves for this cut.
    pub family: &'static str,
    /// The face this cut belongs to.
    pub face: Face,
    /// The weight baked into the cut (its `OS/2` weight class).
    pub weight: f32,
    /// Whether the cut is italic.
    pub italic: bool,
    /// SHA-256 of the embedded bytes.
    pub sha256: &'static str,
    /// The font bytes.
    pub bytes: &'static [u8],
}

/// The general text-size display family (opsz 18).
pub const DISPLAY_TEXT: &str = "Bricolage Grotesque";
/// The display-size cuts (opsz 96) for section heads and board heroes.
pub const DISPLAY_LARGE: &str = "Bricolage Grotesque Display";
/// The page hero cut (opsz 96, wdth 92).
pub const DISPLAY_HERO: &str = "Bricolage Grotesque Hero";
/// The shelf book title cut (opsz 17, wdth 95).
pub const DISPLAY_BOOK: &str = "Bricolage Grotesque Book";
/// The UI family.
pub const UI: &str = "Geist";
/// The identifier family.
pub const MONO: &str = "Geist Mono";
/// The serif family (always set italic); its italic cut is opsz 14.
pub const SERIF: &str = "Newsreader";
/// The lede-size serif (italic, opsz 19).
pub const SERIF_LEDE: &str = "Newsreader Lede";

macro_rules! cut {
    ($file:literal, $family:expr, $face:ident, $weight:literal, $italic:literal, $sha:literal) => {
        Cut {
            file: $file,
            family: $family,
            face: Face::$face,
            weight: $weight,
            italic: $italic,
            sha256: $sha,
            bytes: include_bytes!(concat!("../resources/fonts/", $file)),
        }
    };
}

