/// A bundled font whose bytes no longer match the manifest.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FontMismatch {
    /// The offending file.
    pub file: &'static str,
    /// Its actual SHA-256.
    pub actual: String,
}

impl fmt::Display for FontMismatch {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "bundled font {} has SHA-256 {}; the manifest pins another",
            self.file, self.actual
        )
    }
}

impl std::error::Error for FontMismatch {}

/// Checks every embedded cut against its pinned hash.
///
/// # Errors
/// The first cut whose bytes changed.
pub fn verify() -> Result<(), FontMismatch> {
    for cut in &CUTS {
        let actual = format!("{:x}", Sha256::digest(cut.bytes));
        if actual != cut.sha256 {
            return Err(FontMismatch {
                file: cut.file,
                actual,
            });
        }
    }
    Ok(())
}

/// Verifies and registers every cut with GPUI's text system. Call once per
/// app, before the first window.
///
/// # Errors
/// A hash mismatch, or the platform refusing a font.
pub fn install(cx: &App) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    verify()?;
    let fonts = CUTS
        .iter()
        .map(|cut| Cow::Borrowed(cut.bytes))
        .collect::<Vec<_>>();
    cx.text_system()
        .add_fonts(fonts)
        .map_err(|error| error.to_string().into())
}

/// The family a role resolves to. GPUI then picks the cut nearest the role's
/// weight inside that family (CSS font matching).
#[must_use]
pub fn family(role: TypeRole) -> &'static str {
    match role.face {
        Face::Display if role == ty::HERO => DISPLAY_HERO,
        Face::Display if role == ty::BOOK => DISPLAY_BOOK,
        // The boards pin `opsz 96` on every display-size head.
        Face::Display if role.size >= 24.0 => DISPLAY_LARGE,
        Face::Display => DISPLAY_TEXT,
        Face::Ui => UI,
        Face::Mono => MONO,
        // Chrome sets opsz to the px size; two cuts bracket the ladder.
        Face::Serif if role.size >= 17.0 && role.italic => SERIF_LEDE,
        Face::Serif => SERIF,
    }
}

/// The cut GPUI will select for a role (CSS weight matching within
/// [`family`]); used by tests and the type sheet's annotations.
#[must_use]
pub fn cut(role: TypeRole) -> &'static Cut {
    let family = family(role);
    let candidates = || {
        CUTS.iter()
            .filter(move |cut| cut.family == family && cut.italic == role.italic)
    };
    let wanted = role.weight;
    // CSS Fonts 4 §5.2: for weights above 500 look up first, then down; for
    // 400..=500 look up to 500, then down, then up; below 400 look down first.
    let up = |limit: f32| {
        candidates()
            .filter(move |cut| cut.weight >= wanted && cut.weight <= limit)
            .min_by(|a, b| a.weight.total_cmp(&b.weight))
    };
    let down = || {
        candidates()
            .filter(|cut| cut.weight < wanted)
            .max_by(|a, b| a.weight.total_cmp(&b.weight))
    };
    let chosen = if wanted > 500.0 {
        up(f32::MAX).or_else(down)
    } else if wanted >= 400.0 {
        up(500.0).or_else(down).or_else(|| up(f32::MAX))
    } else {
        down().or_else(|| up(f32::MAX))
    };
    chosen.unwrap_or(&CUTS[8])
}

/// The font features a role turns on.
///
/// Every mono role asks for `zero` (the boards' `.mono` / `.code` rule) and
/// turns `liga` off: the boards render `->` and `=>` as typed, never as
/// Geist Mono's arrow ligatures, and an identifier must read exactly as it is
/// spelled. Geist Mono 1.7 ships no `zero` feature (its default zero is
/// already slashed, as on the boards), so that request is a documented no-op
/// kept for spec parity. `.code`'s `ss02` is not applied: the rendered boards
/// show the default double-storey `a`.
#[must_use]
pub fn features(role: TypeRole) -> FontFeatures {
    static MONO: LazyLock<FontFeatures> = LazyLock::new(|| {
        FontFeatures(Arc::new(vec![
            ("zero".to_owned(), 1),
            ("liga".to_owned(), 0),
        ]))
    });
    match role.face {
        Face::Mono => MONO.clone(),
        Face::Display | Face::Ui | Face::Serif => FontFeatures::default(),
    }
}

/// Sets a [`TypeRole`] on any styled element: family, weight, size, line
/// height, tracking, italic and features, all at the facet's text scale.
pub trait Typeset: Styled + Sized {
    /// Typesets with the active facet's text scale.
    #[must_use]
    fn typeset(self, role: TypeRole, facet: &Facet) -> Self {
        self.typeset_at(role, facet.text_scale)
    }

    /// Typesets at an explicit text scale (1.0 = 100 %).
    #[must_use]
    fn typeset_at(mut self, role: TypeRole, scale: f32) -> Self {
        let size = role.size * scale;
        let text = self.text_style();
        text.font_family = Some(SharedString::new_static(family(role)));
        text.font_weight = Some(FontWeight(role.weight));
        text.font_style = Some(if role.italic {
            FontStyle::Italic
        } else {
            FontStyle::Normal
        });
        text.font_features = Some(features(role));
        text.font_size = Some(px(size).into());
        text.line_height = Some(px(role.line * scale).into());
        text.letter_spacing = Some(px(role.tracking * size));
        self
    }
}

impl<E: Styled> Typeset for E {}

#[cfg(test)]
mod tests {
    use super::{CUTS, cut, family, verify};
    use crate::tokens::{Face, TypeRole, ty};

    const ROLES: [TypeRole; 22] = [
        ty::DISPLAY_XL,
        ty::HERO,
        ty::DISPLAY,
        ty::TITLE,
        ty::BOOK,
        ty::DEPTH,
        ty::HEAD,
        ty::DIALOG,
        ty::PROSE,
        ty::BODY,
        ty::ROW,
        ty::BUTTON,
        ty::SMALL,
        ty::LABEL,
        ty::STATUS,
        ty::CODE,
        ty::MONO_ROW,
        ty::MONO_SMALL,
        ty::LEDE,
        ty::MARGIN,
        ty::CAPTION,
        ty::AXIS,
    ];

    #[test]
    fn manifest_matches_embedded_bytes() {
        assert_eq!(verify(), Ok(()));
    }

    #[test]
    fn every_role_has_an_exact_cut() {
        for role in ROLES {
            let chosen = cut(role);
            assert_eq!(chosen.family, family(role));
            assert_eq!(chosen.italic, role.italic, "{role:?}");
            // The ladder never asks for a weight it has to approximate,
            // except TITLE (650), which has its own cut.
            assert!(
                (chosen.weight - role.weight).abs() < 0.5,
                "{role:?} resolves to {} {}",
                chosen.family,
                chosen.weight
            );
        }
    }

    #[test]
    fn display_roles_pick_their_optical_family() {
        assert_eq!(family(ty::HERO), super::DISPLAY_HERO);
        assert_eq!(family(ty::BOOK), super::DISPLAY_BOOK);
        assert_eq!(family(ty::DISPLAY_XL), super::DISPLAY_LARGE);
        assert_eq!(family(ty::DISPLAY), super::DISPLAY_LARGE);
        assert_eq!(family(ty::TITLE), super::DISPLAY_TEXT);
        assert_eq!(family(ty::DEPTH), super::DISPLAY_TEXT);
        assert_eq!(family(ty::LEDE), super::SERIF_LEDE);
        assert_eq!(family(ty::CAPTION), super::SERIF);
        assert!(
            CUTS.iter()
                .all(|cut| cut.face != Face::Serif || cut.family.starts_with(super::SERIF))
        );
    }
}
